package com.enterprise.procurement.controller.v2;
import com.enterprise.procurement.aspect.OperationLog; import com.enterprise.procurement.business.PurchaseBusinessService; import com.enterprise.procurement.dto.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/purchase-requests") public class PurchaseRequestController {private final PurchaseBusinessService s; public PurchaseRequestController(PurchaseBusinessService s){this.s=s;} @GetMapping public ApiResponse<?> list(java.security.Principal p){return ApiResponse.ok(s.list(p.getName()));} @GetMapping("/{id}") public ApiResponse<?> get(@PathVariable Long id){return ApiResponse.ok(s.get(id));} @PostMapping public ApiResponse<?> create(@Valid @RequestBody PurchaseRequestDtos.Create d,java.security.Principal p){return ApiResponse.ok("草稿已创建",s.createDraft(p.getName(),d));} @PutMapping("/{id}") public ApiResponse<?> update(@PathVariable Long id,@Valid @RequestBody PurchaseRequestDtos.Update d,java.security.Principal p){return ApiResponse.ok(s.updateDraft(id,p.getName(),d));} @DeleteMapping("/{id}") public ApiResponse<?> delete(@PathVariable Long id,java.security.Principal p){s.deleteDraft(id,p.getName());return ApiResponse.ok("已删除",null);} @PostMapping("/{id}/submit") public ApiResponse<?> submit(@PathVariable Long id,java.security.Principal p){return ApiResponse.ok(s.submit(id,p.getName()));} @PostMapping("/{id}/withdraw") public ApiResponse<?> withdraw(@PathVariable Long id,java.security.Principal p){return ApiResponse.ok(s.withdraw(id,p.getName()));}}
